// Python bindings for etebase-rs, implemented with PyO3.
//
// The Python-visible API (class names, method names, enum values as ints and
// the `Error` exception) mirrors the one previously generated by flapigen, so
// `etebase/__init__.py` keeps working unchanged.

use std::sync::{Arc, Mutex, MutexGuard};

use pyo3::create_exception;
use pyo3::exceptions::{PyException, PyValueError};
use pyo3::prelude::*;

use etebase::managers;

create_exception!(etebase_python, Error, PyException);

fn to_py_err(err: etebase::error::Error) -> PyErr {
    Error::new_err(err.to_string())
}

type Result<T> = std::result::Result<T, PyErr>;

trait IntoPyResult<T> {
    fn py(self) -> Result<T>;
}

impl<T> IntoPyResult<T> for std::result::Result<T, etebase::error::Error> {
    fn py(self) -> Result<T> {
        self.map_err(to_py_err)
    }
}

// ---------------------------------------------------------------------------
// Enums: exposed as classes with integer class attributes, and accepted /
// returned as plain ints, exactly like the flapigen bindings did.
// ---------------------------------------------------------------------------

#[pyclass(name = "PrefetchOption", module = "etebase_python", frozen)]
struct PyPrefetchOption;

#[pymethods]
#[allow(non_upper_case_globals)]
impl PyPrefetchOption {
    #[classattr]
    const Auto: u32 = 0;
    #[classattr]
    const Medium: u32 = 1;
}

fn prefetch_from_u32(value: u32) -> Result<etebase::PrefetchOption> {
    match value {
        0 => Ok(etebase::PrefetchOption::Auto),
        1 => Ok(etebase::PrefetchOption::Medium),
        _ => Err(PyValueError::new_err(format!("{} is not valid value for PrefetchOption", value))),
    }
}

#[pyclass(name = "CollectionAccessLevel", module = "etebase_python", frozen)]
struct PyCollectionAccessLevel;

#[pymethods]
#[allow(non_upper_case_globals)]
impl PyCollectionAccessLevel {
    #[classattr]
    const ReadOnly: u32 = 0;
    #[classattr]
    const Admin: u32 = 1;
    #[classattr]
    const ReadWrite: u32 = 2;
}

fn access_level_from_u32(value: u32) -> Result<etebase::CollectionAccessLevel> {
    use etebase::CollectionAccessLevel::*;
    match value {
        0 => Ok(ReadOnly),
        1 => Ok(Admin),
        2 => Ok(ReadWrite),
        _ => Err(PyValueError::new_err(format!("{} is not valid value for CollectionAccessLevel", value))),
    }
}

fn access_level_to_u32(value: etebase::CollectionAccessLevel) -> u32 {
    use etebase::CollectionAccessLevel::*;
    match value {
        ReadOnly => 0,
        Admin => 1,
        ReadWrite => 2,
    }
}

