// ---------------------------------------------------------------------------
// FetchOptions
// ---------------------------------------------------------------------------

#[derive(Clone, Default)]
struct OwnedFetchOptions {
    limit: Option<usize>,
    stoken: Option<String>,
    iterator: Option<String>,
    prefetch: Option<etebase::PrefetchOption>,
    with_collection: Option<bool>,
}

impl OwnedFetchOptions {
    fn to_fetch_options(&self) -> etebase::FetchOptions<'_> {
        let mut ret = etebase::FetchOptions::new();
        if let Some(limit) = self.limit {
            ret = ret.limit(limit);
        }
        if let Some(prefetch) = &self.prefetch {
            ret = ret.prefetch(prefetch);
        }
        if let Some(with_collection) = self.with_collection {
            ret = ret.with_collection(with_collection);
        }
        ret = ret.iterator(self.iterator.as_deref());
        ret = ret.stoken(self.stoken.as_deref());
        ret
    }
}

#[pyclass(name = "FetchOptions", module = "etebase_python")]
#[derive(Clone)]
struct PyFetchOptions(OwnedFetchOptions);

#[pymethods]
impl PyFetchOptions {
    #[new]
    fn new() -> Self {
        Self(OwnedFetchOptions::default())
    }

    fn limit(&mut self, limit: usize) {
        self.0.limit = Some(limit);
    }

    fn prefetch(&mut self, prefetch: u32) -> Result<()> {
        self.0.prefetch = Some(prefetch_from_u32(prefetch)?);
        Ok(())
    }

    fn with_collection(&mut self, with_collection: bool) {
        self.0.with_collection = Some(with_collection);
    }

    #[pyo3(signature = (iterator))]
    fn iterator(&mut self, iterator: Option<String>) {
        self.0.iterator = iterator;
    }

    #[pyo3(signature = (stoken))]
    fn stoken(&mut self, stoken: Option<String>) {
        self.0.stoken = stoken;
    }
}

/// Snapshot the (optional) Python FetchOptions into an owned value.
fn owned_options(options: Option<PyRef<PyFetchOptions>>) -> Option<OwnedFetchOptions> {
    options.map(|x| x.0.clone())
}

macro_rules! with_options {
    ($options:expr, |$opts:ident| $body:expr) => {{
        let owned = owned_options($options);
        let converted = owned.as_ref().map(|x| x.to_fetch_options());
        let $opts = converted.as_ref();
        $body
    }};
}

