// ---------------------------------------------------------------------------
// Collection / Item
// ---------------------------------------------------------------------------

/// Wrapped in a Mutex because `etebase::Collection` is `Send` but not `Sync`.
#[pyclass(name = "Collection", module = "etebase_python")]
struct PyCollection(Mutex<etebase::Collection>);

impl PyCollection {
    fn new(inner: etebase::Collection) -> Self {
        Self(Mutex::new(inner))
    }

    fn lock(&self) -> MutexGuard<'_, etebase::Collection> {
        self.0.lock().unwrap()
    }
}

#[pymethods]
impl PyCollection {
    fn verify(&self) -> bool {
        self.lock().verify().unwrap_or(false)
    }

    fn set_meta(&self, meta: PyRef<PyItemMetadata>) -> Result<()> {
        self.lock().set_meta(&meta.0).py()
    }

    fn get_meta(&self) -> Result<PyItemMetadata> {
        Ok(PyItemMetadata(self.lock().meta().py()?))
    }

    fn set_meta_raw(&self, meta: Vec<u8>) -> Result<()> {
        self.lock().set_meta_raw(&meta).py()
    }

    fn get_meta_raw(&self) -> Result<Vec<u8>> {
        self.lock().meta_raw().py()
    }

    fn set_content(&self, content: Vec<u8>) -> Result<()> {
        self.lock().set_content(&content).py()
    }

    fn get_content(&self) -> Result<Vec<u8>> {
        self.lock().content().py()
    }

    fn delete(&self) -> Result<()> {
        self.lock().delete().py()
    }

    fn is_deleted(&self) -> bool {
        self.lock().is_deleted()
    }

    fn get_uid(&self) -> String {
        self.lock().uid().to_owned()
    }

    fn get_etag(&self) -> String {
        self.lock().etag().to_owned()
    }

    fn get_stoken(&self) -> Option<String> {
        self.lock().stoken().map(str::to_string)
    }

    fn get_access_level(&self) -> u32 {
        access_level_to_u32(self.lock().access_level())
    }

    fn get_item(&self) -> Result<PyItem> {
        Ok(PyItem::new(self.lock().item().py()?))
    }

    fn get_collection_type(&self) -> Result<String> {
        self.lock().collection_type().py()
    }
}

/// Items are shared (Arc) so that list responses and the objects passed back
/// in by the user refer to the same underlying item, as before.
#[pyclass(name = "Item", module = "etebase_python")]
#[derive(Clone)]
struct PyItem {
    inner: Arc<Mutex<etebase::Item>>,
}

impl PyItem {
    fn new(inner: etebase::Item) -> Self {
        Self { inner: Arc::new(Mutex::new(inner)) }
    }

    fn lock(&self) -> MutexGuard<'_, etebase::Item> {
        self.inner.lock().unwrap()
    }
}

#[pymethods]
impl PyItem {
    fn verify(&self) -> bool {
        self.lock().verify().unwrap_or(false)
    }

    fn set_meta(&self, meta: PyRef<PyItemMetadata>) -> Result<()> {
        self.lock().set_meta(&meta.0).py()
    }

    fn get_meta(&self) -> Result<PyItemMetadata> {
        Ok(PyItemMetadata(self.lock().meta().py()?))
    }

    fn set_meta_raw(&self, meta: Vec<u8>) -> Result<()> {
        self.lock().set_meta_raw(&meta).py()
    }

    fn get_meta_raw(&self) -> Result<Vec<u8>> {
        self.lock().meta_raw().py()
    }

    fn set_content(&self, content: Vec<u8>) -> Result<()> {
        self.lock().set_content(&content).py()
    }

    fn get_content(&self) -> Result<Vec<u8>> {
        self.lock().content().py()
    }

    fn delete(&self) -> Result<()> {
        self.lock().delete().py()
    }

    fn is_deleted(&self) -> bool {
        self.lock().is_deleted()
    }

    fn is_missing_content(&self) -> bool {
        self.lock().is_missing_content()
    }

    fn get_uid(&self) -> String {
        self.lock().uid().to_owned()
    }

    fn get_etag(&self) -> String {
        self.lock().etag().to_owned()
    }
}

/// Lock a list of items, keeping the guards alive for the duration of a call.
fn lock_items<'a>(items: &'a [PyRef<'_, PyItem>]) -> Vec<MutexGuard<'a, etebase::Item>> {
    items.iter().map(|x| x.lock()).collect()
}

