#[pyclass(name = "CollectionListResponse", module = "etebase_python")]
struct PyCollectionListResponse(Mutex<etebase::CollectionListResponse<etebase::Collection>>);

#[pymethods]
impl PyCollectionListResponse {
    fn get_stoken(&self) -> Option<String> {
        self.0.lock().unwrap().stoken().map(str::to_string)
    }

    fn get_data(&self) -> Vec<PyCollection> {
        self.0.lock().unwrap().data().iter().cloned().map(PyCollection::new).collect()
    }

    fn is_done(&self) -> bool {
        self.0.lock().unwrap().done()
    }

    fn get_removed_memberships(&self) -> Vec<PyRemovedCollection> {
        self.0.lock().unwrap()
            .removed_memberships()
            .map(|removed| removed.iter().cloned().map(PyRemovedCollection).collect())
            .unwrap_or_default()
    }
}

