#[pyclass(name = "CollectionManager", module = "etebase_python")]
struct PyCollectionManager(managers::CollectionManager);

#[pymethods]
impl PyCollectionManager {
    #[pyo3(signature = (col_uid, fetch_options))]
    fn fetch(&self, col_uid: &str, fetch_options: Option<PyRef<PyFetchOptions>>) -> Result<PyCollection> {
        with_options!(fetch_options, |opts| Ok(PyCollection::new(self.0.fetch(col_uid, opts).py()?)))
    }

    fn create(&self, collection_type: &str, meta: PyRef<PyItemMetadata>, content: Vec<u8>) -> Result<PyCollection> {
        Ok(PyCollection::new(self.0.create(collection_type, &meta.0, &content).py()?))
    }

    fn create_raw(&self, collection_type: &str, meta: Vec<u8>, content: Vec<u8>) -> Result<PyCollection> {
        Ok(PyCollection::new(self.0.create_raw(collection_type, &meta, &content).py()?))
    }

    fn get_item_manager(&self, col: PyRef<PyCollection>) -> Result<PyItemManager> {
        Ok(PyItemManager(self.0.item_manager(&col.lock()).py()?))
    }

    #[pyo3(signature = (collection_type, fetch_options))]
    fn list(&self, collection_type: &str, fetch_options: Option<PyRef<PyFetchOptions>>) -> Result<PyCollectionListResponse> {
        with_options!(fetch_options, |opts| Ok(PyCollectionListResponse(Mutex::new(
            self.0.list(collection_type, opts).py()?
        ))))
    }

    #[pyo3(signature = (collection_types, fetch_options))]
    fn list_multi(
        &self,
        collection_types: Vec<String>,
        fetch_options: Option<PyRef<PyFetchOptions>>,
    ) -> Result<PyCollectionListResponse> {
        with_options!(fetch_options, |opts| Ok(PyCollectionListResponse(Mutex::new(
            self.0.list_multi(collection_types.iter().map(String::as_str), opts).py()?
        ))))
    }

    #[pyo3(signature = (collection, fetch_options))]
    fn upload(&self, collection: PyRef<PyCollection>, fetch_options: Option<PyRef<PyFetchOptions>>) -> Result<()> {
        with_options!(fetch_options, |opts| self.0.upload(&collection.lock(), opts).py())
    }

    #[pyo3(signature = (collection, fetch_options))]
    fn transaction(&self, collection: PyRef<PyCollection>, fetch_options: Option<PyRef<PyFetchOptions>>) -> Result<()> {
        with_options!(fetch_options, |opts| self.0.transaction(&collection.lock(), opts).py())
    }

    fn cache_load(&self, cached: Vec<u8>) -> Result<PyCollection> {
        Ok(PyCollection::new(self.0.cache_load(&cached).py()?))
    }

    fn cache_save(&self, collection: PyRef<PyCollection>) -> Result<Vec<u8>> {
        self.0.cache_save(&collection.lock()).py()
    }

    fn cache_save_with_content(&self, collection: PyRef<PyCollection>) -> Result<Vec<u8>> {
        self.0.cache_save_with_content(&collection.lock()).py()
    }

    fn get_member_manager(&self, col: PyRef<PyCollection>) -> Result<PyCollectionMemberManager> {
        Ok(PyCollectionMemberManager(self.0.member_manager(&col.lock()).py()?))
    }
}

#[pyclass(name = "ItemManager", module = "etebase_python")]
struct PyItemManager(managers::ItemManager);

#[pymethods]
impl PyItemManager {
    #[pyo3(signature = (item_uid, fetch_options))]
    fn fetch(&self, item_uid: &str, fetch_options: Option<PyRef<PyFetchOptions>>) -> Result<PyItem> {
        with_options!(fetch_options, |opts| Ok(PyItem::new(self.0.fetch(item_uid, opts).py()?)))
    }

    fn create(&self, meta: PyRef<PyItemMetadata>, content: Vec<u8>) -> Result<PyItem> {
        Ok(PyItem::new(self.0.create(&meta.0, &content).py()?))
    }

    fn create_raw(&self, meta: Vec<u8>, content: Vec<u8>) -> Result<PyItem> {
        Ok(PyItem::new(self.0.create_raw(&meta, &content).py()?))
    }

    #[pyo3(signature = (fetch_options))]
    fn list(&self, fetch_options: Option<PyRef<PyFetchOptions>>) -> Result<PyItemListResponse> {
        with_options!(fetch_options, |opts| Ok(PyItemListResponse(Mutex::new(self.0.list(opts).py()?))))
    }

    #[pyo3(signature = (item, fetch_options))]
    fn item_revisions(
        &self,
        item: PyRef<PyItem>,
        fetch_options: Option<PyRef<PyFetchOptions>>,
    ) -> Result<PyItemRevisionsListResponse> {
        let item = item.lock();
        with_options!(fetch_options, |opts| Ok(PyItemRevisionsListResponse(Mutex::new(
            self.0.item_revisions(&item, opts).py()?
        ))))
    }

    #[pyo3(signature = (items, fetch_options))]
    fn fetch_updates(
        &self,
        items: Vec<PyRef<PyItem>>,
        fetch_options: Option<PyRef<PyFetchOptions>>,
    ) -> Result<PyItemListResponse> {
        let guards = lock_items(&items);
        with_options!(fetch_options, |opts| Ok(PyItemListResponse(Mutex::new(
            self.0.fetch_updates(guards.iter().map(|x| &**x), opts).py()?
        ))))
    }

    #[pyo3(signature = (items, fetch_options))]
    fn fetch_multi(&self, items: Vec<String>, fetch_options: Option<PyRef<PyFetchOptions>>) -> Result<PyItemListResponse> {
        with_options!(fetch_options, |opts| Ok(PyItemListResponse(Mutex::new(
            self.0.fetch_multi(items.iter().map(String::as_str), opts).py()?
        ))))
    }

    #[pyo3(signature = (items, deps, fetch_options))]
    fn batch(
        &self,
        items: Vec<PyRef<PyItem>>,
        deps: Option<Vec<PyRef<PyItem>>>,
        fetch_options: Option<PyRef<PyFetchOptions>>,
    ) -> Result<()> {
        let items = lock_items(&items);
        let items = items.iter().map(|x| &**x);
        with_options!(fetch_options, |opts| match &deps {
            Some(deps) => {
                let deps = lock_items(deps);
                self.0.batch_deps(items, deps.iter().map(|x| &**x), opts).py()
            }
            None => self.0.batch(items, opts).py(),
        })
    }

    #[pyo3(signature = (items, deps, fetch_options))]
    fn transaction(
        &self,
        items: Vec<PyRef<PyItem>>,
        deps: Option<Vec<PyRef<PyItem>>>,
        fetch_options: Option<PyRef<PyFetchOptions>>,
    ) -> Result<()> {
        let items = lock_items(&items);
        let items = items.iter().map(|x| &**x);
        with_options!(fetch_options, |opts| match &deps {
            Some(deps) => {
                let deps = lock_items(deps);
                self.0.transaction_deps(items, deps.iter().map(|x| &**x), opts).py()
            }
            None => self.0.transaction(items, opts).py(),
        })
    }

    fn download_content(&self, item: PyRef<PyItem>) -> Result<()> {
        self.0.download_content(&mut item.lock()).py()
    }

    fn upload_content(&self, item: PyRef<PyItem>) -> Result<()> {
        self.0.upload_content(&item.lock()).py()
    }

    fn cache_load(&self, cached: Vec<u8>) -> Result<PyItem> {
        Ok(PyItem::new(self.0.cache_load(&cached).py()?))
    }

    fn cache_save(&self, item: PyRef<PyItem>) -> Result<Vec<u8>> {
        self.0.cache_save(&item.lock()).py()
    }

    fn cache_save_with_content(&self, item: PyRef<PyItem>) -> Result<Vec<u8>> {
        self.0.cache_save_with_content(&item.lock()).py()
    }
}

