// ---------------------------------------------------------------------------
// Module
// ---------------------------------------------------------------------------

#[pymodule]
fn etebase_python(m: &Bound<'_, PyModule>) -> PyResult<()> {
    m.add("Error", m.py().get_type::<Error>())?;
    m.add_class::<PyUtils>()?;
    m.add_class::<PyClient>()?;
    m.add_class::<PyUser>()?;
    m.add_class::<PyAccount>()?;
    m.add_class::<PyRemovedCollection>()?;
    m.add_class::<PyCollectionListResponse>()?;
    m.add_class::<PyItemListResponse>()?;
    m.add_class::<PyItemRevisionsListResponse>()?;
    m.add_class::<PyPrefetchOption>()?;
    m.add_class::<PyFetchOptions>()?;
    m.add_class::<PyItemMetadata>()?;
    m.add_class::<PyCollectionManager>()?;
    m.add_class::<PyItemManager>()?;
    m.add_class::<PyCollectionAccessLevel>()?;
    m.add_class::<PyCollection>()?;
    m.add_class::<PyItem>()?;
    m.add_class::<PyUserProfile>()?;
    m.add_class::<PyInvitationListResponse>()?;
    m.add_class::<PyCollectionInvitationManager>()?;
    m.add_class::<PySignedInvitation>()?;
    m.add_class::<PyCollectionMember>()?;
    m.add_class::<PyMemberListResponse>()?;
    m.add_class::<PyCollectionMemberManager>()?;
    Ok(())
}
